import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long th = nextLong();
        long[] a = new long[n];
        long lo = 0, hi = 0;
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
            hi = Math.max(hi, a[i]);
        }
        // Total energy is non-increasing in the barrier: find the last barrier that keeps it >= th.
        while (lo < hi) {
            long mid = (lo + hi + 1) / 2, sum = 0;
            for (long v : a)
                if (v > mid) sum += v - mid;
            if (sum >= th) lo = mid;
            else hi = mid - 1;
        }
        System.out.println(lo);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	th := nextInt()
	a := make([]int64, n)
	var lo, hi int64
	for i := range a {
		a[i] = nextInt()
		hi = max(hi, a[i])
	}
	// Total energy is non-increasing in the barrier: find the last barrier that keeps it >= th.
	for lo < hi {
